files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #2a2a4a;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --radius: 4px;
  --shadow: 4px 4px 0 #0a0a1a;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 400px;
}

.pixel-title {
  font-size: 1.5rem;
  margin: 0 0 20px;
  text-align: center;
  letter-spacing: 1px;
  color: var(--accent);
  text-transform: uppercase;
}

.field {
  margin-bottom: 20px;
  border: none;
  padding: 0;
}

label, legend {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 0.95rem;
}

input[type="number"] {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--primary);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  outline: none;
  transition: border-color 0.15s;
}

input[type="number"]:hover {
  border-color: var(--accent);
}

input[type="number"]:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.help {
  display: block;
  margin-top: 4px;
  font-size: 0.8rem;
  color: var(--muted);
}

.tip-buttons {
  display: flex;
  gap: 8px;
}

.tip-btn {
  flex: 1;
  padding: 12px 8px;
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font);
  color: var(--text);
  background: var(--primary);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.tip-btn:hover {
  background: var(--accent);
  border-color: var(--accent);
}

.tip-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: scale(0.96);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.results {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 2px dashed var(--border);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 12px;
}

.result-row:last-child {
  margin-bottom: 0;
}

.result-label {
  font-size: 1rem;
  color: var(--muted);
}

.result-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .pixel-title {
    font-size: 1.25rem;
  }
  .tip-buttons {
    flex-direction: column;
  }
  .tip-btn {
    width: 100%;
  }
}

document.addEventListener('DOMContentLoaded', function () {
  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = document.querySelectorAll('.tip-btn');
  var tipAmountEl = document.getElementById('tip-amount');
  var totalPerPersonEl = document.getElementById('total-per-person');

  var selectedTip = 0;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value) || 0;
    var people = parseInt(peopleInput.value, 10) || 1;
    if (people < 1) people = 1;

    var tip = bill * (selectedTip / 100);
    var totalPerPerson = (bill + tip) / people;

    tipAmountEl.textContent = formatCurrency(tip);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function selectTip(percent) {
    selectedTip = percent;
    tipButtons.forEach(function (btn) {
      var isActive = parseInt(btn.dataset.tip, 10) === percent;
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var percent = parseInt(btn.dataset.tip, 10);
      selectTip(percent);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Initialize with 15% selected
  selectTip(15);
});
